from (values
  (1, 'Role models, media and strategies to improve participation', 'Which organisation publishes data on participation in sport in England?', 'The Food Standards Agency', 'Sport England', 'The World Anti-Doping Agency', 'The Met Office', 'B', 'J587 expects you to know sources such as Sport England, National Governing Bodies (NGBs) and the DCMS.', 'foundation', 'recall', 'AO1'),
  (2, 'Role models, media and strategies to improve participation', 'A council builds a new sports centre in an area that has none. Which strategy to improve participation is this?', 'Selective attention', 'Sponsorship', 'Provision', 'Promotion', 'C', 'Provision is making facilities and activities available. Promotion is advertising them; access is making them easy to reach and use.', 'foundation', 'applied', 'AO2'),
  (3, 'Role models, media and strategies to improve participation', 'A leisure centre advertises free sessions on social media to attract more teenage girls. Which strategy is this?', 'Promotion', 'Commercialisation', 'Provision', 'Access', 'A', 'Promotion raises awareness and encourages people to take part.', 'foundation', 'applied', 'AO2'),
  (4, 'Commercialisation: media and sponsorship', 'Which is a negative effect of the media on the commercialisation of sport?', 'More people can watch sport live from home', 'Performers become better known to the public', 'Sports receive more money from TV deals', 'Less-covered sports struggle to find sponsors', 'D', 'The golden triangle links sport, sponsorship and the media. Sports with little coverage find it harder to attract sponsors.', 'higher', 'applied', 'AO3')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
