insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'cbd30e39-b038-4728-8713-5d7ef6af833a'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Sportsmanship, gamesmanship and deviance', 'What is deviance in sport?', 'Behaviour that breaks the rules or moral values', 'Bending the rules to gain an advantage', 'Playing fairly and respecting opponents', 'Celebrating a win together with teammates', 'A', 'Examples include taking banned drugs, match fixing and violence. Bending the rules without breaking them is gamesmanship.', 'foundation', 'recall', 'AO1'),
  (2, 'Sportsmanship, gamesmanship and deviance', 'Which is an example of gamesmanship?', 'Taking a banned substance', 'Deliberately wasting time when winning', 'Shaking hands with the opponents', 'Kicking the ball out when an opponent is injured', 'B', 'Gamesmanship stretches the rules to gain an advantage without breaking them.', 'foundation', 'applied', 'AO2'),
  (3, 'Sportsmanship, gamesmanship and deviance', 'Which is an example of sportsmanship?', 'Arguing angrily with the referee', 'Pretending to be fouled to win a free kick', 'Distracting an opponent as they take a shot', 'Kicking the ball out for an injured opponent', 'D', 'Sportsmanship is fair, generous behaviour that respects opponents and officials.', 'foundation', 'applied', 'AO2'),
  (4, 'Sportsmanship, gamesmanship and deviance', 'Which is an example of deviance in sport?', 'Taking a long time to prepare for a free kick', 'Applauding an opponent''s good play', 'Fixing the result of a match for money', 'Appealing to the umpire for a wicket', 'C', 'Match fixing breaks the rules and the law. Slow preparation is gamesmanship and appealing is part of the game.', 'foundation', 'applied', 'AO2'),
  (5, 'Sportsmanship, gamesmanship and deviance', 'A coach tells their players to keep winding up an opponent so that the opponent loses their temper. This is best described as…', 'Selective attention', 'Gamesmanship', 'Sportsmanship', 'Positive thinking', 'B', 'Trying to upset an opponent to gain an advantage is gamesmanship. If it led to fighting, that would be deviance.', 'higher', 'applied', 'AO2'),
  (6, 'Drugs in sport', 'Why might a sports performer decide to take performance-enhancing drugs?', 'To make their own performance worse', 'To make the competition fairer for everyone', 'Pressure to win and the rewards of success', 'Because drug testing has been abolished', 'C', 'Reasons include pressure from coaches or the public, fame and money from winning, and recovering from injury faster.', 'foundation', 'recall', 'AO1'),
  (7, 'Drugs in sport', 'What is a possible side effect of anabolic steroids?', 'Liver damage and aggression', 'A permanently lower heart rate', 'Improved sleep every night', 'Better eyesight and hearing', 'A', 'Steroids increase muscle mass and strength but can cause liver damage, heart problems and aggression.', 'foundation', 'recall', 'AO1'),
  (8, 'Drugs in sport', 'In which sport is a performer most likely to misuse beta blockers?', 'Archery', 'Marathon running', 'Rugby', 'Weightlifting', 'A', 'Beta blockers lower heart rate and reduce shaking, which helps in precision sports such as archery, shooting and snooker.', 'foundation', 'applied', 'AO2'),
  (9, 'Drugs in sport', 'How might drug use by elite performers affect young people who play sport?', 'They will all stop playing sport at once', 'It will make them train more safely', 'It has no effect, as they never watch sport', 'They may see drug-taking as normal', 'D', 'Drug use damages the image of sport and can send the wrong message to young performers.', 'higher', 'applied', 'AO3'),
  (10, 'Violence in sport', 'Which is a common reason for player violence in sport?', 'Frustration at a decision', 'Playing in good weather', 'Wearing the correct kit', 'A large crowd cheering them on', 'A', 'Reasons for player violence include frustration, provocation, the importance of the event and rivalry.', 'foundation', 'recall', 'AO1'),
  (11, 'Violence in sport', 'Why is player violence more likely in a local derby match?', 'Derbies always have fewer officials', 'Fierce rivalry raises emotions', 'Players in derbies are paid less', 'Derby matches are always shorter', 'B', 'High-stakes games with fierce rivalry increase emotions, which can lead to violence.', 'foundation', 'applied', 'AO2'),
  (12, 'Violence in sport', 'Which of these is an example of player violence?', 'Punching an opponent after a heavy tackle', 'Celebrating a goal with the fans', 'Making a hard but fair tackle within the rules', 'Shouting encouragement to teammates', 'A', 'A hard tackle within the rules is part of the game. Violence is aggressive behaviour outside the rules.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
